class NumMatrix{int m,n;int[][]b,a;void add(int r,int c,int d){for(int i=r+1;i<=m;i+=i&-i)for(int j=c+1;j<=n;j+=j&-j)b[i][j]+=d;}int sum(int r,int c){int x=0;for(int i=r+1;i>0;i-=i&-i)for(int j=c+1;j>0;j-=j&-j)x+=b[i][j];return x;}public NumMatrix(int[][]x){m=x.length;n=m>0?x[0].length:0;b=new int[m+1][n+1];a=new int[m][n];for(int i=0;i<m;i++)for(int j=0;j<n;j++)update(i,j,x[i][j]);}public void update(int r,int c,int v){int d=v-a[r][c];a[r][c]=v;add(r,c,d);}public int sumRegion(int r1,int c1,int r2,int c2){return sum(r2,c2)-sum(r1-1,c2)-sum(r2,c1-1)+sum(r1-1,c1-1);}}
